<section style="max-width:1000px;margin:25px auto"><p style="font:11px Consolas;letter-spacing:2px;color:var(--primary)">GOLDENSITE / BÚSQUEDA</p><h1>Encuentra lo que necesitas.</h1><form method="get" action="/buscar" style="display:flex;gap:12px;flex-wrap:wrap"><label style="flex:1;min-width:180px">Buscar en el sitio<input name="q" value="<?= $e($q) ?>" maxlength="120" required minlength="2" style="display:block;width:100%;box-sizing:border-box;padding:14px;background:var(--card-bg);color:var(--text-color);border:1px solid var(--primary);border-radius:8px"></label><button class="btn-cta" type="submit" style="padding:14px;border:0;border-radius:8px;align-self:end">Buscar</button></form><?php if ($status): ?><p role="alert"><?= $e($status) ?></p><?php endif ?><p role="status"><?= $result['total'] ?> resultados</p><?php foreach ($result['data'] as $row): ?><article style="padding:25px 0;border-bottom:1px solid var(--primary)"><small><?= $e($row['type']) ?></small><h2><a href="<?= $e($row['url']) ?>" style="color:var(--primary)"><?= $e($row['title']) ?></a></h2><p data-nx-content style="line-height:1.7;opacity:.85"><?= $e($row['excerpt']) ?></p><span style="font:12px Consolas"><?= $e($row['url']) ?></span></article><?php endforeach ?><div style="display:flex;gap:15px;margin-top:24px"><?php if ($result['page']>1): ?><a href="?q=<?= rawurlencode($q) ?>&amp;page=<?= $result['page']-1 ?>">Anterior</a><?php endif ?><?php if ($result['page']<$result['pages']): ?><a href="?q=<?= rawurlencode($q) ?>&amp;page=<?= $result['page']+1 ?>">Siguiente</a><?php endif ?></div></section>
